  await saveDate(f, 0, '2000-02-29');
  await applyRange(f, '2000-02-29', '');
  await saveDate(f, 0, '');
  assert.deepEqual(f.titles(), []);
});

test('archived projects can apply ranges without enabling edits or writing data', async () => {
