  const saved = structuredClone(f.tasks);
  await applyRange(f, ' 2024-02-29 ', ' 2024-03-01 ');
  assert.deepEqual(f.titles(), ['Second', 'Third']);
  assert.equal(f.app.querySelector('#due-from').value, '2024-02-29');
