  assert.deepEqual(f.titles(), ['First', 'Second']);
  await applyRange(f, '2024-02-29', '');
  assert.deepEqual(f.titles(), ['Second', 'Third']);
  await applyRange(f, '2024-02-29', '2024-02-29');
