  await searchTasks(f, '');
  assert.deepEqual(f.titles(), [title]);
  assert.equal(f.tasks[0].title, title);
  assert.equal(f.priority.value, 'High');
  assert.equal(f.completion.value, 'Open');
  assert.equal(f.app.querySelector('#due-from').value, '2025-01-01');
});

